import re


def rule_phmsa_region_office(doc: dict) -> list[dict]:
    try:
        region_specs = [
            (
                "Eastern Region",
                "Eastern",
                [
                    re.compile(r"\bEastern\s+Region\b", re.IGNORECASE),
                    re.compile(r"840\s+Bear\s+Tavern\s+Road", re.IGNORECASE),
                    re.compile(r"West\s+Trenton,\s*NJ", re.IGNORECASE),
                ],
            ),
            (
                "Southern Region",
                "Southern",
                [
                    re.compile(r"\bSouthern\s+Region\b", re.IGNORECASE),
                    re.compile(r"230\s+Peachtree\s+Street(?:\s+N\.?W\.?)?", re.IGNORECASE),
                    re.compile(r"Atlanta,\s*GA\s*30303", re.IGNORECASE),
                ],
            ),
            (
                "Central Region",
                "Central",
                [
                    re.compile(r"\bCentral\s+Region\b", re.IGNORECASE),
                    re.compile(r"901\s+Locust\s+Street", re.IGNORECASE),
                    re.compile(r"Kansas\s+City,\s*MO\s*64106", re.IGNORECASE),
                ],
            ),
            (
                "Western Region",
                "Western",
                [
                    re.compile(r"\bWestern\s+Region\b", re.IGNORECASE),
                    re.compile(r"12300\s+W\.?\s+Dakota\s+Ave\.?", re.IGNORECASE),
                    re.compile(r"Lakewood,\s*CO\s*80228", re.IGNORECASE),
                ],
            ),
            (
                "Southwest Region",
                "Southwest",
                [
                    re.compile(r"\bSouthwest\s+Region\b", re.IGNORECASE),
                    re.compile(r"8701\s+S\.?\s+Gessner", re.IGNORECASE),
                    re.compile(r"Houston,\s*TX\s*77074", re.IGNORECASE),
                    re.compile(r"Houston\s+TX\s*77074", re.IGNORECASE),
                ],
            ),
        ]

        lines = doc.get("lines") or []
        ordered_lines = sorted(
            lines,
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("line_no", 10**9),
            ),
        )

        def build_spans(region_phrase: str, region_short: str, item: dict | None) -> list[dict]:
            spans = [{"text": region_phrase}]
            if region_short != region_phrase:
                spans.append({"text": region_short})
            if item is not None:
                for span in spans:
                    span["page_no"] = item.get("page_no")
                    span["line_no"] = item.get("line_no")
            return spans

        # Prefer concrete header/footer lines, because they tend to identify the
        # issuing office directly and avoid false positives from body text.
        for item in ordered_lines[:80] + ordered_lines[-80:]:
            text = (item.get("text") or "").strip()
            if not text:
                continue
            for region_phrase, region_short, patterns in region_specs:
                if any(p.search(text) for p in patterns):
                    return build_spans(region_phrase, region_short, item)

        full_text = doc.get("text") or ""
        for region_phrase, region_short, patterns in region_specs:
            if any(p.search(full_text) for p in patterns):
                return build_spans(region_phrase, region_short, None)

        return []
    except Exception:
        return []

import re


_REGION = r"(?:Central|Eastern|Southern|Southwest|Western)"
_DIRECTOR_REGION_RE = re.compile(
    rf"\b(?:Acting\s+)?Director(?:\s+of)?[, ]+(?:the\s+)?(?:PHMSA[, ]+)?{_REGION}\s+Region\b",
    re.IGNORECASE,
)
_REGION_DIRECTOR_RE = re.compile(rf"\b(?:Acting\s+)?{_REGION}\s+Region\s+Director\b", re.IGNORECASE)
_PHMSA_REGION_RE = re.compile(rf"\bPHMSA[, ]+{_REGION}\s+Region\b", re.IGNORECASE)
_OFFICE_RE = re.compile(
    r"\b(?:Office of Pipeline Safety|Pipeline and Hazardous Materials Safety Administration)\b",
    re.IGNORECASE,
)
_NAME_RE = re.compile(
    r"^[A-Z][A-Za-z.'-]*(?:\s+[A-Z]\.)?(?:\s+[A-Z][A-Za-z.'-]*(?:\s+[A-Z]\.)?){0,4}$"
)


def rule_phmsa_region_office_signature(doc: dict) -> list[dict]:
    try:
        lines = [s for s in (doc.get("lines") or []) if isinstance(s, dict)]
        if not lines:
            return []

        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def meta(span: dict) -> dict:
            out = {"text": norm(span.get("text") or "")}
            if "page_no" in span:
                out["page_no"] = span["page_no"]
            if "line_no" in span:
                out["line_no"] = span["line_no"]
            return out

        def is_name_line(text: str) -> bool:
            t = norm(text)
            if not t or len(t) > 70:
                return False
            if any(ch.isdigit() for ch in t):
                return False
            if _OFFICE_RE.search(t) or "director" in t.lower():
                return False
            return bool(_NAME_RE.match(t))

        def score_candidate(index: int, text: str) -> int:
            t = norm(text)
            low = t.lower()
            score = 0
            if _DIRECTOR_REGION_RE.search(t):
                score += 5
            if _REGION_DIRECTOR_RE.search(t):
                score += 4
            if _PHMSA_REGION_RE.search(t):
                score += 3
            if _OFFICE_RE.search(t):
                score += 3
            if "director" in low and _OFFICE_RE.search(t):
                score += 2
            if index >= len(lines) // 2:
                score += 1
            prev_text = norm(lines[index - 1].get("text") or "") if index > 0 else ""
            next_text = norm(lines[index + 1].get("text") or "") if index + 1 < len(lines) else ""
            if is_name_line(prev_text):
                score += 2
            if _OFFICE_RE.search(next_text):
                score += 2
            return score

        best = None
        best_score = 0
        for i, span in enumerate(lines):
            text = norm(span.get("text") or "")
            if not text:
                continue
            if not (
                _DIRECTOR_REGION_RE.search(text)
                or _REGION_DIRECTOR_RE.search(text)
                or _PHMSA_REGION_RE.search(text)
            ):
                continue

            score = score_candidate(i, text)
            if score < 5:
                continue

            start = i
            end = i
            if i > 0 and is_name_line(lines[i - 1].get("text") or ""):
                start = i - 1
            if i + 1 < len(lines) and _OFFICE_RE.search(norm(lines[i + 1].get("text") or "")):
                end = i + 1

            combined = " ".join(norm(lines[j].get("text") or "") for j in range(start, end + 1))
            candidate = {
                "text": combined,
                **{k: lines[start][k] for k in ("page_no", "line_no") if k in lines[start]},
            }

            if score > best_score or (score == best_score and best is not None and len(candidate["text"]) > len(best["text"])):
                best = candidate
                best_score = score

        return [best] if best else []
    except Exception:
        return []

